const t=[{id:"respiratory-ent-asthma-001",topicId:"respiratory-ent-asthma",question:"Что представляют собой синусы?",options:["Воздухоносные полости в костях черепа, соединённые с полостью носа","Скопления лимфоидной ткани в области носоглотки","Хрящевые кольца, образующие стенку трахеи","Мышечные складки, разделяющие носовую и ротовую полости"],correctIndex:0,explanation:"Синусы — это воздухоносные полости в костях черепа, соединённые с полостью носа.",difficulty:"easy",tags:["анатомия","синусы"]},{id:"respiratory-ent-asthma-002",topicId:"respiratory-ent-asthma",question:"Какие синусы относятся к основным придаточным пазухам носа?",options:["Височные, теменные, затылочные и скуловые","Гайморовы, лобные, решётчатые и клиновидные","Носовые, глоточные, гортанные и трахеальные","Верхние, средние, нижние и задние"],correctIndex:1,explanation:"Основные синусы: гайморовы (верхнечелюстные), лобные (фронтальные), решётчатые и клиновидные.",difficulty:"easy",tags:["анатомия","синусы"]},{id:"respiratory-ent-asthma-003",topicId:"respiratory-ent-asthma",question:"Какое второе название имеют гайморовы пазухи?",options:["Фронтальные","Клиновидные","Решётчатые","Верхнечелюстные"],correctIndex:3,explanation:"Гайморовы пазухи также называются верхнечелюстными.",difficulty:"easy",tags:["анатомия","синусы"]},{id:"respiratory-ent-asthma-004",topicId:"respiratory-ent-asthma",question:"Какие пазухи носят также название фронтальных?",options:["Лобные","Гайморовы","Решётчатые","Клиновидные"],correctIndex:0,explanation:"Лобные пазухи также называются фронтальными.",difficulty:"easy",tags:["анатомия","синусы"]},{id:"respiratory-ent-asthma-005",topicId:"respiratory-ent-asthma",question:"Сколько основных функций выполняют синусы?",options:["Три","Четыре","Пять","Шесть"],correctIndex:2,explanation:"Синусы выполняют пять функций: увлажнение и согревание воздуха, фильтрация воздуха, облегчение веса черепа, формирование голоса (резонанс) и защита (амортизация).",difficulty:"medium",tags:["физиология","синусы"]},{id:"respiratory-ent-asthma-006",topicId:"respiratory-ent-asthma",question:"Какую роль играет слизь синусов и носа при фильтрации воздуха?",options:["Растворяет пыль и выводит её через кровь","Задерживает вирусы, бактерии и пыль","Разрушает микроорганизмы ферментами полностью","Изменяет химический состав вдыхаемого воздуха"],correctIndex:1,explanation:"При фильтрации воздуха слизь задерживает вирусы, бактерии и пыль.",difficulty:"medium",tags:["физиология","синусы"]},{id:"respiratory-ent-asthma-007",topicId:"respiratory-ent-asthma",question:"Каким образом синусы облегчают вес черепа?",options:["За счёт истончения костной ткани в области лица","За счёт замещения кости хрящом","За счёт того, что полости содержат воздух, делая кости легче","За счёт уменьшения количества костей черепа"],correctIndex:2,explanation:"Полости синусов содержат воздух, что делает кости черепа легче.",difficulty:"medium",tags:["физиология","синусы"]},{id:"respiratory-ent-asthma-008",topicId:"respiratory-ent-asthma",question:"Какая функция синусов связана с формированием голоса?",options:["Фильтрация воздуха","Амортизация при травмах","Согревание вдыхаемого воздуха","Резонанс — усиление звучания голоса"],correctIndex:3,explanation:"Синусы участвуют в формировании голоса, обеспечивая резонанс и усиливая звучание голоса.",difficulty:"medium",tags:["физиология","синусы"]},{id:"respiratory-ent-asthma-009",topicId:"respiratory-ent-asthma",question:"В чём заключается защитная (амортизационная) функция синусов?",options:["Воздушные полости смягчают удар при травмах лица","Слизистая вырабатывает антитела против бактерий","Пазухи изолируют головной мозг от переохлаждения","Полости препятствуют проникновению инфекции в кровь"],correctIndex:0,explanation:"Защита (амортизация) состоит в том, что воздушные полости смягчают удар при травмах лица.",difficulty:"medium",tags:["физиология","синусы"]},{id:"respiratory-ent-asthma-010",topicId:"respiratory-ent-asthma",question:"Что такое синусит?",options:["Разрастание лимфоидной ткани в носоглотке","Воспаление слизистой оболочки одной или нескольких придаточных пазух носа","Воспаление слизистой гортани","Искривление носовой перегородки"],correctIndex:1,explanation:"Синусит — воспаление слизистой оболочки одной или нескольких придаточных пазух носа.",difficulty:"easy",tags:["синусит","определение"]},{id:"respiratory-ent-asthma-011",topicId:"respiratory-ent-asthma",question:"Воспаление каких пазух называется гайморитом?",options:["Лобных","Клиновидных","Гайморовых","Решётчатых"],correctIndex:2,explanation:"Гайморит — воспаление гайморовых (верхнечелюстных) пазух.",difficulty:"easy",tags:["синусит","терминология"]},{id:"respiratory-ent-asthma-012",topicId:"respiratory-ent-asthma",question:"Как называется воспаление лобных пазух?",options:["Гайморит","Этмоидит","Тонзиллит","Фронтит"],correctIndex:3,explanation:"Фронтит — воспаление лобных пазух.",difficulty:"easy",tags:["синусит","терминология"]},{id:"respiratory-ent-asthma-013",topicId:"respiratory-ent-asthma",question:"Какой характер выделений из носа характерен для синусита?",options:["Слизисто-гнойные выделения","Обильные водянистые прозрачные выделения","Кровянистые выделения с прожилками","Выделения полностью отсутствуют"],correctIndex:0,explanation:"К симптомам синусита относятся слизисто-гнойные выделения.",difficulty:"medium",tags:["синусит","симптомы"]},{id:"respiratory-ent-asthma-014",topicId:"respiratory-ent-asthma",question:"При каком движении усиливается боль у пациента с синуситом?",options:["При повороте туловища","При наклоне головы","При поднятии рук вверх","При глубоком приседании"],correctIndex:1,explanation:"Для синусита характерна боль при наклоне головы.",difficulty:"medium",tags:["синусит","симптомы"]},{id:"respiratory-ent-asthma-015",topicId:"respiratory-ent-asthma",question:"Какое нарушение со стороны органов чувств возникает при синусите?",options:["Снижение слуха","Ухудшение зрения","Снижение обоняния","Потеря вкусовых ощущений"],correctIndex:2,explanation:"Одним из симптомов синусита является снижение обоняния.",difficulty:"medium",tags:["синусит","симптомы"]},{id:"respiratory-ent-asthma-016",topicId:"respiratory-ent-asthma",question:"При каком характере воспалительного процесса при синусите чаще повышается температура?",options:["При аллергическом","При вирусном","При грибковом","При бактериальном"],correctIndex:3,explanation:"Повышение температуры при синусите отмечается чаще при бактериальном процессе.",difficulty:"medium",tags:["синусит","симптомы"]},{id:"respiratory-ent-asthma-017",topicId:"respiratory-ent-asthma",question:"Воспаление каких структур называется тонзиллитом?",options:["Нёбных миндалин (гланд)","Слизистой гортани","Придаточных пазух носа","Лимфоидной ткани носоглотки"],correctIndex:0,explanation:"Тонзиллит — это воспаление нёбных миндалин (гланд).",difficulty:"easy",tags:["тонзиллит","определение"]},{id:"respiratory-ent-asthma-018",topicId:"respiratory-ent-asthma",question:"Как называется острая форма тонзиллита?",options:["Фарингит","Ангина","Ларингит","Аденоидит"],correctIndex:1,explanation:"Острая форма тонзиллита называется ангиной; заболевание может быть также хроническим.",difficulty:"easy",tags:["тонзиллит","терминология"]},{id:"respiratory-ent-asthma-019",topicId:"respiratory-ent-asthma",question:"Из какой ткани состоят миндалины?",options:["Из хрящевой ткани","Из гладкомышечной ткани","Из лимфоидной ткани","Из железистого эпителия"],correctIndex:2,explanation:"Миндалины состоят из лимфоидной ткани и являются частью иммунной системы.",difficulty:"medium",tags:["тонзиллит","анатомия"]},{id:"respiratory-ent-asthma-020",topicId:"respiratory-ent-asthma",question:"Частью какой системы организма являются миндалины?",options:["Эндокринной","Пищеварительной","Нервной","Иммунной"],correctIndex:3,explanation:"Миндалины являются частью иммунной системы.",difficulty:"easy",tags:["тонзиллит","физиология"]},{id:"respiratory-ent-asthma-021",topicId:"respiratory-ent-asthma",question:"Какие клетки, убивающие микробы, содержатся в миндалинах?",options:["Лимфоциты и фагоциты","Эритроциты и тромбоциты","Остеоциты и хондроциты","Нейроны и глиальные клетки"],correctIndex:0,explanation:"Миндалины содержат лимфоциты и фагоциты — клетки, которые убивают микробы.",difficulty:"medium",tags:["тонзиллит","физиология"]},{id:"respiratory-ent-asthma-022",topicId:"respiratory-ent-asthma",question:"Какую образную характеристику дают миндалинам с точки зрения защиты дыхательных путей?",options:["«Последний барьер» кровеносной системы","«Первая линия обороны» дыхательных путей","«Резервный орган» иммунитета","«Фильтр глубоких отделов» лёгких"],correctIndex:1,explanation:"Миндалины являются «первой линией обороны» дыхательных путей.",difficulty:"medium",tags:["тонзиллит","физиология"]},{id:"respiratory-ent-asthma-023",topicId:"respiratory-ent-asthma",question:"От чего защищают миндалины организм?",options:["От переохлаждения верхних дыхательных путей","От механических повреждений глотки","От вирусов и бактерий, попадающих через рот и нос","От избыточного поступления пыли в лёгкие"],correctIndex:2,explanation:"Миндалины защищают организм от вирусов и бактерий, попадающих через рот и нос.",difficulty:"medium",tags:["тонзиллит","физиология"]},{id:"respiratory-ent-asthma-024",topicId:"respiratory-ent-asthma",question:"В формировании иммунитета у какой возрастной группы особенно участвуют миндалины?",options:["У пожилых людей","У людей среднего возраста","У подростков в период полового созревания","У детей"],correctIndex:3,explanation:"Миндалины участвуют в формировании иммунитета у детей.",difficulty:"medium",tags:["тонзиллит","физиология"]},{id:"respiratory-ent-asthma-025",topicId:"respiratory-ent-asthma",question:"В каком анатомическом отделе располагаются нёбные миндалины?",options:["В ротоглотке","В носоглотке","В гортани","В верхнем отделе трахеи"],correctIndex:0,explanation:"Нёбные миндалины (гланды) находятся в ротоглотке, по обеим сторонам зева.",difficulty:"medium",tags:["тонзиллит","анатомия"]},{id:"respiratory-ent-asthma-026",topicId:"respiratory-ent-asthma",question:"Между какими структурами располагаются нёбные миндалины?",options:["Между голосовыми связками","Между передней и задней нёбными дужками","Между хоанами и носовой перегородкой","Между надгортанником и корнем языка"],correctIndex:1,explanation:"Нёбные миндалины располагаются между передней и задней нёбными дужками, по обеим сторонам зева.",difficulty:"hard",tags:["тонзиллит","анатомия"]},{id:"respiratory-ent-asthma-027",topicId:"respiratory-ent-asthma",question:"Что такое аденоид?",options:["Воспаление слизистой оболочки гортани","Опухолевое образование в области придаточных пазух","Увеличение и разрастание лимфоидной ткани в области перехода носовой полости в носоглотку","Скопление гноя в гайморовой пазухе"],correctIndex:2,explanation:"Аденоид — это увеличение и разрастание лимфоидной ткани в области перехода носовой полости в носоглотку.",difficulty:"medium",tags:["аденоид","определение"]},{id:"respiratory-ent-asthma-028",topicId:"respiratory-ent-asthma",question:"К чему приводит выраженная гипертрофия аденоида?",options:["К нарушению глотания твёрдой пищи","К потере голоса и осиплости","К повышению внутричерепного давления","К сужению просвета носоглотки и затруднению носового дыхания"],correctIndex:3,explanation:"При выраженной гипертрофии аденоид значительно суживает просвет носоглотки и затрудняет носовое дыхание.",difficulty:"medium",tags:["аденоид","осложнения"]},{id:"respiratory-ent-asthma-029",topicId:"respiratory-ent-asthma",question:"Какие проявления вызывает выраженная гипертрофия аденоида?",options:["Храп, частые простуды и снижение слуха","Кожную сыпь и зуд","Судороги и мышечную слабость","Боли в суставах и утреннюю скованность"],correctIndex:0,explanation:"Гипертрофия аденоида вызывает храп, частые простуды и снижение слуха.",difficulty:"medium",tags:["аденоид","симптомы"]},{id:"respiratory-ent-asthma-030",topicId:"respiratory-ent-asthma",question:"Какие варианты лечения применяются для предотвращения прогрессирования аденоидита и тонзиллита?",options:["Только физиотерапевтическое лечение","Консервативное (без операции) или хирургическое при выраженных изменениях","Исключительно хирургическое удаление в любом случае","Только наблюдение без какого-либо вмешательства"],correctIndex:1,explanation:"Лечение может быть консервативным (без операции) или хирургическим, если изменения сильно выражены.",difficulty:"medium",tags:["аденоид","лечение"]},{id:"respiratory-ent-asthma-031",topicId:"respiratory-ent-asthma",question:"Что представляет собой ангина?",options:["Хроническое разрастание лимфоидной ткани носоглотки","Воспаление слизистой оболочки трахеи","Острое воспаление нёбных миндалин","Воспаление бронхов с выделением мокроты"],correctIndex:2,explanation:"Ангина — острое воспаление нёбных миндалин.",difficulty:"easy",tags:["терминология"]},{id:"respiratory-ent-asthma-032",topicId:"respiratory-ent-asthma",question:"Воспаление слизистой какого органа называется ларингитом?",options:["Трахеи","Бронхов","Глотки","Гортани"],correctIndex:3,explanation:"Ларингит — воспаление слизистой гортани.",difficulty:"easy",tags:["терминология"]},{id:"respiratory-ent-asthma-033",topicId:"respiratory-ent-asthma",question:"Какое заболевание представляет собой воспаление бронхов?",options:["Бронхит","Трахеит","Ларингит","Плеврит"],correctIndex:0,explanation:"Бронхит — воспаление бронхов.",difficulty:"easy",tags:["терминология"]},{id:"respiratory-ent-asthma-034",topicId:"respiratory-ent-asthma",question:"Трахеит — это воспалительное поражение какого органа?",options:["Гортани","Трахеи","Бронхов","Нёбных миндалин"],correctIndex:1,explanation:"Трахеит — воспаление трахеи.",difficulty:"easy",tags:["терминология"]},{id:"respiratory-ent-asthma-035",topicId:"respiratory-ent-asthma",question:"Как определяется бронхиальная астма?",options:["Как острое инфекционное поражение альвеол лёгких","Как наследственное нарушение синтеза сурфактанта","Как хроническое неинфекционное заболевание дыхательных путей воспалительного характера","Как обратимое сужение гортани аллергической природы"],correctIndex:2,explanation:"Бронхиальная астма — это хроническое неинфекционное заболевание дыхательных путей воспалительного характера.",difficulty:"medium",tags:["астма","определение"]},{id:"respiratory-ent-asthma-036",topicId:"respiratory-ent-asthma",question:"Чем характеризуется приступ бронхиальной астмы по типу дыхания?",options:["Длительным вдохом и коротким выдохом","Полной остановкой дыхания на 20–30 секунд","Равномерным поверхностным дыханием без хрипов","Коротким резким вдохом и шумным длительным выдохом"],correctIndex:3,explanation:"Приступ бронхиальной астмы характеризуется коротким резким вдохом и шумным длительным выдохом.",difficulty:"medium",tags:["астма","клиника"]},{id:"respiratory-ent-asthma-037",topicId:"respiratory-ent-asthma",question:"Чем обычно сопровождается приступ бронхиальной астмы?",options:["Кашлем с вязкой мокротой и громкими свистящими хрипами","Сухим лающим кашлем без отделяемого","Кровохарканьем и болью за грудиной","Обильным отделением жидкой прозрачной мокроты"],correctIndex:0,explanation:"Приступ астмы сопровождается кашлем с вязкой мокротой и громкими свистящими хрипами.",difficulty:"medium",tags:["астма","клиника"]},{id:"respiratory-ent-asthma-038",topicId:"respiratory-ent-asthma",question:"После чего часто развивается приступ бронхиальной астмы?",options:["После приёма пищи","После предвестников","После физиотерапевтических процедур","После длительного сна"],correctIndex:1,explanation:"Приступ бронхиальной астмы часто развивается после предвестников.",difficulty:"medium",tags:["астма","клиника"]},{id:"respiratory-ent-asthma-039",topicId:"respiratory-ent-asthma",question:"Какие методы функциональной диагностики применяются при бронхиальной астме?",options:["Электрокардиография и эхокардиография","Допплерография и ангиография","Спирометрия и пикфлоуметрия","Бронхоскопия и биопсия лёгкого"],correctIndex:2,explanation:"Методы диагностики астмы включают оценку данных спирометрии и пикфлоуметрии.",difficulty:"medium",tags:["астма","диагностика"]},{id:"respiratory-ent-asthma-040",topicId:"respiratory-ent-asthma",question:"Какие исследования, помимо спирометрии и пикфлоуметрии, входят в диагностику бронхиальной астмы?",options:["Коагулограмма и определение D-димера","Общий анализ мочи и проба Зимницкого","Бактериологический посев мокроты и антибиотикограмма","Аллергопробы, клинические и иммунологические анализы крови"],correctIndex:3,explanation:"Диагностика астмы включает аллергопробы, клинические и иммунологические анализы крови.",difficulty:"medium",tags:["астма","диагностика"]},{id:"respiratory-ent-asthma-041",topicId:"respiratory-ent-asthma",question:"Какие группы препаратов применяются в лечении бронхиальной астмы?",options:["Аэрозольные бета-адреномиметики и м-холинолитики","Диуретики и сердечные гликозиды","Гемостатики и ангиопротекторы","Наркотические анальгетики и миорелаксанты"],correctIndex:0,explanation:"В лечении бронхиальной астмы используются аэрозольные бета-адреномиметики и м-холинолитики.",difficulty:"medium",tags:["астма","лечение"]},{id:"respiratory-ent-asthma-042",topicId:"respiratory-ent-asthma",question:"Какая группа препаратов применяется при тяжёлых формах бронхиальной астмы?",options:["Антибиотики широкого спектра","Глюкокортикостероиды","Антикоагулянты","Муколитики"],correctIndex:1,explanation:"При тяжёлых формах бронхиальной астмы применяются глюкокортикостероиды.",difficulty:"medium",tags:["астма","лечение"]},{id:"respiratory-ent-asthma-043",topicId:"respiratory-ent-asthma",question:"Какие факторы являются наиболее опасными провоцирующими для развития бронхиальной астмы?",options:["Физические перегрузки","Приём жирной пищи","Экзогенные аллергены","Изменения атмосферного давления"],correctIndex:2,explanation:"Наиболее опасными провоцирующими факторами для развития бронхиальной астмы являются экзогенные аллергены.",difficulty:"medium",tags:["астма","этиология"]},{id:"respiratory-ent-asthma-044",topicId:"respiratory-ent-asthma",question:"Какие аллергены являются самыми распространёнными при бронхиальной астме?",options:["Промышленные химические вещества","Лекарственные препараты для наружного применения","Металлы и сплавы","Бытовые аллергены — домашняя и книжная пыль"],correctIndex:3,explanation:"Самыми распространёнными аллергенами являются бытовые — домашняя и книжная пыль, пыльца растений, шерсть, перхоть животных, а также пищевые аллергены.",difficulty:"medium",tags:["астма","этиология"]},{id:"respiratory-ent-asthma-045",topicId:"respiratory-ent-asthma",question:"Каким образом инфекционные факторы участвуют в этиопатогенезе бронхиальной астмы?",options:["Микроорганизмы и продукты их жизнедеятельности выступают в качестве аллергенов, вызывая сенсибилизацию","Они непосредственно разрушают стенку бронхов","Они блокируют выработку гистамина в организме","Они полностью подавляют иммунный ответ"],correctIndex:0,explanation:"Микроорганизмы и продукты их жизнедеятельности могут выступать в качестве аллергенов, вызывая сенсибилизацию организма.",difficulty:"hard",tags:["астма","этиология"]},{id:"respiratory-ent-asthma-046",topicId:"respiratory-ent-asthma",question:"Какие дополнительные факторы занимают важное место в этиологии бронхиальной астмы?",options:["Гиподинамия, ожирение и курение","Переохлаждение, отягощённая наследственность и стрессовые состояния","Недостаток калия, магния и кальция","Работа во вредных отраслях и черепно-мозговые травмы"],correctIndex:1,explanation:"Переохлаждение, отягощённая наследственность и стрессовые состояния занимают одно из важных мест в этиологии бронхиальной астмы.",difficulty:"medium",tags:["астма","этиология"]},{id:"respiratory-ent-asthma-047",topicId:"respiratory-ent-asthma",question:"Какой характер носит одышка при бронхиальной астме?",options:["Постоянная в течение суток","Возникающая только в положении лёжа","Эпизодическая","Появляющаяся исключительно после еды"],correctIndex:2,explanation:"Одним из основных симптомов астмы является эпизодическая одышка.",difficulty:"medium",tags:["астма","симптомы"]},{id:"respiratory-ent-asthma-048",topicId:"respiratory-ent-asthma",question:"В какое время суток особенно беспокоит кашель при бронхиальной астме?",options:["Сразу после пробуждения днём","В середине дня","Только в вечерние часы после ужина","Ночью и под утро"],correctIndex:3,explanation:"При бронхиальной астме кашель беспокоит особенно ночью и под утро.",difficulty:"medium",tags:["астма","симптомы"]},{id:"respiratory-ent-asthma-049",topicId:"respiratory-ent-asthma",question:"Какая фаза дыхания затруднена при бронхиальной астме?",options:["Выдох","Вдох","Обе фазы в равной степени","Ни одна из фаз не затруднена"],correctIndex:0,explanation:"Для бронхиальной астмы характерен затруднённый выдох.",difficulty:"medium",tags:["астма","симптомы"]},{id:"respiratory-ent-asthma-050",topicId:"respiratory-ent-asthma",question:"Какие ощущения в грудной клетке испытывает пациент с бронхиальной астмой?",options:["Жжение за грудиной, отдающее в левую руку","Чувство тяжести и давления в груди","Резкую колющую боль при вдохе","Пульсацию в области сердца"],correctIndex:1,explanation:"К основным симптомам астмы относится чувство тяжести и давления в груди.",difficulty:"medium",tags:["астма","симптомы"]},{id:"respiratory-ent-asthma-051",topicId:"respiratory-ent-asthma",question:"При каких условиях усиливаются симптомы бронхиальной астмы?",options:["В тепле, в покое и после сна","После приёма горячей пищи","На холоде, при контакте с аллергеном и после нагрузки","Только при повышенной влажности воздуха"],correctIndex:2,explanation:"Симптомы астмы усиливаются на холоде, при контакте с аллергеном и после нагрузки.",difficulty:"medium",tags:["астма","симптомы"]},{id:"respiratory-ent-asthma-052",topicId:"respiratory-ent-asthma",question:"Какой характер течения свойственен симптомам бронхиальной астмы?",options:["Постоянный без периодов улучшения","Медленно нарастающий в течение месяцев","Волнообразный только в холодное время года","Приступообразный"],correctIndex:3,explanation:"Симптомам бронхиальной астмы свойственна приступообразность.",difficulty:"medium",tags:["астма","симптомы"]},{id:"respiratory-ent-asthma-053",topicId:"respiratory-ent-asthma",question:"Какое изменение окраски кожи и губ служит поводом срочно вызвать скорую помощь при астме?",options:["Посинение (цианоз)","Пожелтение (иктеричность)","Покраснение (гиперемия)","Появление мраморного рисунка"],correctIndex:0,explanation:"Посинение губ и кожи (цианоз) относится к опасным признакам, требующим срочного вызова скорой помощи.",difficulty:"medium",tags:["астма","неотложные состояния"]},{id:"respiratory-ent-asthma-054",topicId:"respiratory-ent-asthma",question:"Какой признак со стороны дыхания при приступе астмы указывает на угрожающее состояние?",options:["Затруднение только выдоха","Затруднение и вдоха, и выдоха","Редкое глубокое дыхание","Кашель с прозрачной мокротой"],correctIndex:1,explanation:"К опасным признакам относится затруднённый вдох и выдох, а также выраженная одышка.",difficulty:"hard",tags:["астма","неотложные состояния"]},{id:"respiratory-ent-asthma-055",topicId:"respiratory-ent-asthma",question:"Какой признак со стороны применения препарата требует срочного вызова скорой помощи при приступе астмы?",options:["Появление лёгкой сухости во рту после ингаляции","Необходимость повторить ингаляцию через 4 часа","Отсутствие эффекта от ингалятора","Незначительное учащение дыхания после ингаляции"],correctIndex:2,explanation:"Отсутствие эффекта от ингалятора является опасным признаком и поводом срочно вызвать скорую помощь.",difficulty:"medium",tags:["астма","неотложные состояния"]},{id:"respiratory-ent-asthma-056",topicId:"respiratory-ent-asthma",question:"Какие вегетативные и психические проявления входят в число опасных признаков при приступе астмы?",options:["Сонливость и заторможенность","Повышение аппетита и жажда","Замедление пульса и сухость кожи","Учащённый пульс, холодный пот и ощущение паники"],correctIndex:3,explanation:"К опасным признакам относятся учащённый пульс, холодный пот и ощущение паники.",difficulty:"medium",tags:["астма","неотложные состояния"]}];export{t as default};
